#!/usr/bin/env python3
"""Build the Pelvic Gym static journal. Standard library only; run from any directory."""
from pathlib import Path
from html import escape
import json, math, re, xml.etree.ElementTree as ET
from datetime import date

ROOT = Path(__file__).resolve().parents[1]
BASE = '/pelvic_gym'
ORIGIN = 'https://bestme.mobi'
DATE = '2026-10-24'
DISPLAY_DATE = 'October 24, 2026'
APP = 'https://apps.apple.com/app/id6478076577'
ARTICLES = []
for source in sorted((ROOT / '_pelvic_gym/content').glob('*.json')):
    ARTICLES.extend(json.loads(source.read_text()))
ORDER = ['pelvic-floor-exercises-for-women','how-to-do-kegel-exercises','leaking-urine-when-coughing','postpartum-pelvic-floor-recovery','tight-vs-weak-pelvic-floor','how-often-to-do-kegels','how-long-do-kegels-take-to-work','pelvic-floor-exercises-menopause','kegel-exercise-mistakes','pelvic-floor-relaxation']
ORDER += ['pelvic-floor-therapy-what-to-expect', 'pelvic-floor-exercises-after-c-section', 'pelvic-floor-exercises-during-pregnancy', 'running-and-pelvic-floor', 'pelvic-floor-and-constipation', 'bladder-training-vs-kegels', 'urinary-urgency-in-women', 'pelvic-organ-prolapse-exercise', 'painful-sex-and-pelvic-floor', 'peeing-at-night-women', 'kegel-exercises-lying-sitting-standing', 'slow-and-fast-kegel-exercises', 'bladder-diary-for-women', 'kegel-app-vs-biofeedback-trainer', 'kegel-weights-and-trainers', 'yoga-pilates-and-pelvic-floor', 'pelvic-floor-exercises-after-hysterectomy', 'pelvic-floor-and-heavy-lifting', 'breathing-during-kegel-exercises', 'bladder-habits-water-caffeine']
ORDER += [a['slug'] for a in ARTICLES if a['slug'] not in ORDER]
BY_SLUG = {a['slug']:a for a in ARTICLES}
ARTICLES.sort(key=lambda a: (-int(a.get('datePublished', DATE).replace('-', '')), ORDER.index(a['slug'])))
LATEST = max(a.get('dateModified', a.get('datePublished', DATE)) for a in ARTICLES)
def display_date(value): return date.fromisoformat(value).strftime('%B %d, %Y').replace(' 0', ' ')

CATEGORIES = {
    'Getting started': {'slug':'getting-started','title':'Get to know your pelvic floor.','seo':'Pelvic Floor & Kegel Exercise Guides for Beginners | Pelvic Gym','description':'Learn how to find your pelvic floor, practice Kegels, understand exercise positions and choose suitable support with these practical beginner guides.','intro':'Start with the movement, then explore the questions that help you choose a suitable routine. These guides explain technique, training tools, and what professional support can offer.'},
    'Bladder & symptoms': {'slug':'bladder-and-symptoms','title':'Understand what your symptoms may be telling you.','seo':'Bladder Leaks, Urgency & Pelvic Floor Symptoms | Pelvic Gym','description':'Explore practical guides to bladder leaks, urgency, pelvic floor tension, constipation and pain, with clear information about when to seek individual care.','intro':'A cough-related leak, a sudden urge, and persistent pain can need different care. Explore common patterns, prepare for an appointment, and learn why symptoms alone cannot establish a diagnosis.'},
    'Life stages': {'slug':'life-stages','title':'Care for the stage you’re in.','seo':'Pelvic Floor Care in Pregnancy, Postpartum & Menopause','description':'Understand pelvic floor care through pregnancy, birth, menopause and surgery. Explore recovery questions and practical ways to discuss your needs with a clinician.','intro':'Your needs can change through pregnancy, recovery after birth, menopause, and surgery. Find information that helps you discuss your circumstances without comparing yourself with somebody else’s timeline.'},
    'Everyday habits': {'slug':'everyday-habits','title':'Make room for a routine that fits.','seo':'Pelvic Floor Exercise Routines & Everyday Habits | Pelvic Gym','description':'Build practical pelvic floor habits with guides to exercise frequency, progress, breathing, movement and bladder routines that fit your individual needs.','intro':'Useful routines fit real life. Learn how to organize practice, follow a care plan, observe progress, and keep movement enjoyable without turning your day into a constant workout.'}
}
def category_url(name): return BASE+'/guides/'+CATEGORIES[name]['slug']+'/'

def e(s): return escape(str(s), quote=True)
def plain(s): return re.sub('<[^>]+>', ' ', s)
def url(a): return f'{BASE}/articles/{a["slug"]}/'
def minutes(a): return max(3,math.ceil(len(plain(a['quickAnswer']+' '+' '.join(a['takeaways'])+' '+' '.join(x['html'] for x in a['sections'])+' '+' '.join(x['answer'] for x in a['faqs'])).split())/210))
def save(path, text):
    f = ROOT / path.lstrip('/')
    f.parent.mkdir(parents=True,exist_ok=True)
    f.write_text(text,encoding='utf-8')

def app_link(page, place, label='Get Pelvic Gym', style='btn coral'):
    return f'<a class="store-badge {"compact" if place=="header" else ""}" href="{APP}?utm_source=bestme&amp;utm_medium=website&amp;utm_campaign=pelvic_journal&amp;utm_content={e(page)}_{e(place)}" data-app-cta="{e(place)}" aria-label="Download Pelvic Gym on the App Store"><img src="{BASE}/assets/app-store-badge.svg" width="180" height="60" alt="Download on the App Store"></a>'

