def header(page):
    return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap nav"><a class="brand" href="{BASE}/" aria-label="Pelvic Gym journal home"><img src="{BASE}/assets/app-icon.webp" width="42" height="42" alt=""><span>pelvic gym<small>The wellness journal</small></span></a><nav class="nav-links" aria-label="Main navigation"><a href="{BASE}/#guides">Articles</a><a class="nav-about" href="{BASE}/about/">Our approach</a>{app_link(page,'header','Get the app','btn small')}</nav></div></header>'''

def footer():
    return f'''<footer class="footer"><div class="wrap"><div class="footer-main"><div><a class="brand" href="{BASE}/"><span>pelvic gym<small>A little care, every day.</small></span></a><p>Clear, considered guides to your pelvic floor. Published by the makers of Pelvic Gym for iPhone.</p></div><nav class="footer-links" aria-label="Footer"><a href="{BASE}/#guides">All articles</a><a href="{BASE}/about/">About &amp; editorial policy</a><a href="{BASE}/privacy/">Website privacy</a><button type="button" class="privacy-choices" data-privacy-choices hidden>Privacy choices</button><a href="/pelvic-gym-privacy-policy.html">App privacy</a><a href="/pelvic-gym-terms-of-use.html">App terms</a><a href="mailto:contact@bestme.mobi">Contact us</a></nav></div><div class="footer-bottom"><span>© 2026 Pelvic Gym · Aleksandr Korenev</span><span>For education. Not a diagnosis or a substitute for individual medical care.</span></div></div></footer>'''

def consent_panel():
    return f'''<section class="consent-panel" data-consent-panel aria-labelledby="consent-heading" hidden><div><h2 id="consent-heading">Help us improve the journal</h2><p>May we use Google Analytics to measure visits, articles viewed and App Store clicks? Analytics cookies are optional. <a href="{BASE}/privacy/">Read our privacy notice</a>.</p></div><div class="consent-actions"><button class="btn outline" type="button" data-consent-choice="denied">Decline</button><button class="btn coral" type="button" data-consent-choice="granted">Allow analytics</button></div></section>'''


def page_shell(title, desc, path, body, page='home', schemas=None, article=False, noindex=False):
    canonical=ORIGIN+path
    schema = [{'@context':'https://schema.org','@type':'Organization','@id':ORIGIN+BASE+'/#publisher','name':'Pelvic Gym','url':ORIGIN+BASE+'/','logo':ORIGIN+BASE+'/assets/apple-touch-icon.png'}]
    schema.extend(schemas or [])
    graph='\n'.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False).replace('</','<\\/')+'</script>' for s in schema)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{canonical}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}"><meta name="theme-color" content="#faf7f2"><meta name="referrer" content="strict-origin-when-cross-origin"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:site_name" content="Pelvic Gym"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN}{BASE}/assets/editorial-social.jpg"><meta property="og:image:alt" content="A quiet moment of self-care in a sunlit room"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(desc)}"><meta name="twitter:image" content="{ORIGIN}{BASE}/assets/editorial-social.jpg"><link rel="icon" type="image/png" href="{BASE}/assets/favicon.png"><link rel="apple-touch-icon" href="{BASE}/assets/apple-touch-icon.png"><link rel="stylesheet" href="{BASE}/assets/site.css"><script defer src="{BASE}/assets/analytics.js"></script><script defer src="{BASE}/assets/site.js"></script>{graph}</head><body data-page="{e(page)}">{header(page)}{body}{footer()}{consent_panel()}</body></html>'''

def card(a, filtered=False):
    i=ORDER.index(a['slug'])
    return f'''<article class="article-card" {'data-article-card data-category="'+e(a['category'])+'"' if filtered else ''}><a class="card-visual" href="{url(a)}" tabindex="-1" aria-hidden="true">{art(i)}</a><div class="card-meta"><a href="{category_url(a['category'])}">{e(a['category'])}</a><span>{minutes(a)} min read</span></div><h3><a href="{url(a)}">{e(a['title'])}</a></h3><p>{e(a['excerpt'])}</p><a class="text-link" href="{url(a)}" aria-label="Read {e(a['title'])}">Read the guide <span aria-hidden="true">↗</span></a></article>'''

def cta(a):
    if a.get('cta') == 'assessment':
        return f'''<aside class="article-cta assessment" aria-label="Your next step"><p class="eyebrow">Your next step</p><h2>Start with the right support.</h2><p>If you have pain, pressure, or trouble relaxing, a pelvic health professional can help you work out what your muscles need. An exercise app cannot make that assessment.</p><p>If a clinician recommends strengthening as part of your plan, Pelvic Gym offers guided workouts to support a regular routine.</p>{app_link(a['slug'],'article_end','Explore Pelvic Gym','btn')}<small>For iPhone. In-app purchases. Use exercises that fit your individual care plan.</small></aside>'''
    return f'''<aside class="article-cta" aria-label="About the Pelvic Gym app"><p class="eyebrow">Put your plan into practice</p><h2>A little support for your routine.</h2><p>When pelvic floor strengthening is right for you, Pelvic Gym’s guided workouts can help you make space for practice. Follow the plan and technique recommended by your healthcare professional.</p>{app_link(a['slug'],'article_end')}<small>For iPhone. In-app purchases. The app does not diagnose symptoms or replace professional care.</small></aside>'''

def build_home():
    featured=BY_SLUG['pelvic-floor-exercises-for-women']
    filters=''.join(f'<button type="button" class="filter" data-filter="{e(c)}" aria-pressed="{str(c=="all").lower()}">{"All articles" if c=="all" else e(c)}</button>' for c in ['all','Getting started','Bladder & symptoms','Life stages','Everyday habits'])
    body=f'''<main id="main"><div class="wrap"><section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow coral-text">For your body. At your pace.</p><h1 id="hero-title">Get to know<br>your pelvic floor.<br><em>Feel more you.</em></h1><p>Honest answers to the questions you might not ask out loud. Explore pelvic floor health, everyday habits, and care through life’s changes.</p><div class="actions"><a class="btn coral" href="#guides">Find your guide <span aria-hidden="true">↓</span></a><a class="text-link" href="{url(featured)}">New here? Start with the basics ↗</a></div></div><div class="hero-art"><img src="{BASE}/assets/editorial-1280.webp" srcset="{BASE}/assets/editorial-640.webp 640w, {BASE}/assets/editorial-1280.webp 1168w" sizes="(max-width:760px) 100vw, 45vw" width="1168" height="880" alt="A woman taking a quiet moment for herself in a sunlit room" fetchpriority="high"><div class="hero-note"><span>Small moments.<br>More understanding.</span><small>Your body is worth the care.</small></div></div></section><div class="principles" aria-label="Our approach"><div><span aria-hidden="true">✳</span> Grounded in trusted health sources</div><div><span aria-hidden="true">↗</span> Practical, pressure-free guidance</div><div><span aria-hidden="true">♡</span> Made for real life</div></div><section class="start-section" aria-labelledby="start-heading"><div class="section-head"><div><p class="eyebrow">A good place to begin</p><h2 id="start-heading">Meet your pelvic floor.</h2></div><p>Start with understanding. Then find the next step that makes sense for you.</p></div><div class="start-grid"><a class="feature-guide" href="{url(featured)}"><div><p class="eyebrow">The essential guide · {minutes(featured)} min</p><h3>Pelvic floor exercises: where to begin</h3><p>What these muscles do, how training works, and why relaxation matters too.</p><span class="read-link">Read the beginner’s guide ↗</span></div><div class="art-symbol">{art(0)}</div></a><div class="start-secondary"><a class="mini-guide" href="{BASE}/articles/how-to-do-kegel-exercises/"><div><p class="eyebrow">Know the technique</p><h3>How do I know I’m doing Kegels correctly?</h3></div><span class="arrow" aria-hidden="true">↗</span></a><a class="mini-guide" href="{BASE}/articles/tight-vs-weak-pelvic-floor/"><div><p class="eyebrow">Listen to your body</p><h3>Does my pelvic floor need strengthening—or help relaxing?</h3></div><span class="arrow" aria-hidden="true">↗</span></a></div></div></section><section class="library" id="guides" aria-labelledby="guides-title"><div class="section-head"><div><p class="eyebrow">The journal</p><h2 id="guides-title">A little knowledge goes a long way.</h2></div><p>From your first Kegel to the changes of menopause, find answers for the moment you’re in.</p></div><div class="library-tools"><div class="filters" aria-label="Filter guides by topic">{filters}</div><label class="search-box"><span class="visually-hidden">Search guides</span><input id="article-search" type="search" placeholder="Find a topic…" autocomplete="off"><span aria-hidden="true">⌕</span></label></div><p id="results-count" class="visually-hidden" role="status" aria-live="polite">Guides to explore</p><div class="cards">{''.join(card(a,True) for a in ARTICLES)}</div><p id="no-results" class="empty" hidden>No articles match that search. Clear your search or try “Kegel,” “leaks,” or “menopause.”</p></section><aside class="safety-strip"><h2>More squeezing isn’t always the answer.</h2><div><p>A pelvic floor needs to relax as well as contract. If exercises hurt, symptoms worsen, or you have trouble emptying your bladder or bowel, pause and seek individual advice.</p><a class="text-link" href="{BASE}/articles/tight-vs-weak-pelvic-floor/">Understand tightness and weakness ↗</a></div></aside><section class="app-section" id="app" aria-labelledby="app-heading"><div><p class="eyebrow">Meet Pelvic Gym for iPhone</p><h2 id="app-heading">Make a little room<br>for yourself.</h2><p>Learning is a beginning. When strengthening suits your needs, guided workouts can help you make practice part of your day.</p>{app_link('home','app_section','Explore on the App Store','btn')}<small>Available for iPhone · Free download with in-app purchases</small></div><div class="app-visual"><div class="app-panel"><img src="{BASE}/assets/app-icon.webp" width="68" height="68" alt="Pelvic Gym app icon" loading="lazy"><h3>Pelvic Gym</h3><p>A companion for your practice.</p><div class="app-feature"><span aria-hidden="true">◌</span> Guided Kegel workouts</div><div class="app-feature"><span aria-hidden="true">↗</span> Training plans</div><div class="app-feature"><span aria-hidden="true">♡</span> Space for a daily habit</div></div></div></section><section class="newsletter-free"><p class="eyebrow">Our promise to you</p><h2>Helpful information.<br>No miracle claims.</h2><p>Our articles link to established health organizations and explain where advice needs to be personal. Read clear explanations, practical next steps, and guidance on when to seek individual care.</p><a class="text-link" href="{BASE}/about/">Read our editorial approach ↗</a></section></div></main>'''
    schemas=[{'@context':'https://schema.org','@type':'CollectionPage','name':'Pelvic floor health guides for women','url':ORIGIN+BASE+'/','description':'Practical guides to pelvic floor exercises, bladder symptoms and life stages.','mainEntity':{'@type':'ItemList','itemListElement':[{'@type':'ListItem','position':i+1,'name':a['title'],'url':ORIGIN+url(a)} for i,a in enumerate(ARTICLES)]}}]
    save(BASE+'/index.html',page_shell('Pelvic Floor Health & Kegel Guides for Women | Pelvic Gym','Explore practical guides to Kegel exercises, bladder leaks, postpartum recovery and menopause. Clear answers, trusted sources and Pelvic Gym for iPhone.',BASE+'/',body,schemas=schemas))

def build_article(a):
    path=url(a)
    published=a.get('datePublished', DATE)
    modified=a.get('dateModified', published)
    checked=a.get('sourcesChecked', DATE)
    toc=''.join(f'<a href="#{e(s["id"])}">{e(s["title"])}</a>' for s in a['sections'])
    sections=''.join(f'<section aria-labelledby="{e(s["id"])}"><h2 id="{e(s["id"])}">{e(s["title"])}</h2>{s["html"]}</section>' for s in a['sections'])
    faqs=''.join(f'<details class="faq-item"><summary>{e(f["question"])}</summary><p>{e(f["answer"])}</p></details>' for f in a['faqs'])
    sources=''.join(f'<li><a href="{e(s["url"])}">{e(s["title"])}</a></li>' for s in a['sources'])
    body=f'''<div class="reading-progress" aria-hidden="true"></div><main id="main" class="wrap"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="{BASE}/">Pelvic Gym</a><span aria-hidden="true">/</span><a href="{BASE}/#guides">Articles</a><span aria-hidden="true">/</span><a href="{category_url(a['category'])}">{e(a['category'])}</a></nav><header class="article-header"><p class="eyebrow coral-text">{e(a['category'])} / A Pelvic Gym guide</p><h1>{e(a['title'])}</h1><p class="article-dek">{e(a['excerpt'])}</p><div class="byline"><span>By <a href="{BASE}/about/">Pelvic Gym</a></span><time datetime="{published}">{display_date(published)}</time><span>{minutes(a)} min read</span><button class="print-btn" type="button" data-print>Print this guide</button></div><p class="review-note">Educational content · <a href="{BASE}/about/">Our editorial standards</a> · Sources linked below</p></header><div class="article-layout"><article class="article-body"><div class="quick-answer"><h2>The short answer</h2><p>{e(a['quickAnswer'])}</p></div><div class="takeaways"><h2>What to take away</h2><ul>{''.join('<li>'+e(t)+'</li>' for t in a['takeaways'])}</ul></div>{sections}<section aria-labelledby="common-questions"><h2 id="common-questions">Common questions</h2>{faqs}</section>{cta(a)}<section aria-labelledby="sources"><h2 id="sources">Sources &amp; further reading</h2><p class="source-list">The guidance above draws on these public health and clinical resources, consulted {display_date(checked)}. Sources support general education; they have not reviewed or endorsed Pelvic Gym.</p><ol class="source-list">{sources}</ol></section><p class="article-end">Published by the developer of Pelvic Gym. This article is educational and cannot tell you which treatment is right for you. <a href="{BASE}/about/">How we create our articles</a> · <a href="mailto:contact@bestme.mobi?subject=Article%20correction">Suggest a correction</a></p></article><aside class="toc" aria-label="On this page"><p class="eyebrow">In this guide</p><a href="#main">The short answer</a>{toc}<a href="#common-questions">Common questions</a><a href="#sources">Sources &amp; further reading</a><div class="sidebar-note">Your symptoms deserve individual care. If you’re unsure about your technique or what your muscles need, a pelvic health professional can help.</div></aside></div><section class="related" aria-labelledby="related-heading"><p class="eyebrow">Keep exploring</p><h2 id="related-heading">A helpful next read.</h2><div class="cards">{''.join(card(BY_SLUG[s]) for s in a['related'] if s in BY_SLUG and s!=a['slug'])}</div></section></main>'''
    schemas=[{'@context':'https://schema.org','@type':'Article','headline':a['title'],'description':a['description'],'image':[ORIGIN+BASE+'/assets/editorial-social.jpg'],'datePublished':published+'T00:00:00+04:00','dateModified':modified+'T00:00:00+04:00','author':{'@type':'Organization','name':'Pelvic Gym','url':ORIGIN+BASE+'/about/'},'publisher':{'@id':ORIGIN+BASE+'/#publisher'},'mainEntityOfPage':{'@type':'WebPage','@id':ORIGIN+path},'articleSection':a['category'],'inLanguage':'en','citation':[s['url'] for s in a['sources']]},{'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Pelvic Gym','item':ORIGIN+BASE+'/'},{'@type':'ListItem','position':2,'name':a['category'],'item':ORIGIN+category_url(a['category'])},{'@type':'ListItem','position':3,'name':a['title'],'item':ORIGIN+path}]}]
    save(path+'index.html',page_shell(a['seoTitle'],a['description'],path,body,page=a['slug'],schemas=schemas,article=True))

def build_information():
    about=f'''<main id="main" class="wrap"><article class="prose-page"><p class="eyebrow">Our approach</p><h1>Clear information.<br>Considered care.</h1><p>This journal is published by Aleksandr Korenev, the developer of Pelvic Gym, an iPhone app with guided pelvic floor workouts. Our aim is to help women understand common pelvic floor questions and decide on a useful next step.</p><h2>Who creates the articles?</h2><p>These articles draw on the public health and clinical sources linked within each guide. They have not been independently reviewed by a doctor or pelvic health physiotherapist. We do not claim clinical credentials or describe these articles as medically reviewed.</p><h2>How we use sources</h2><p>We prioritize national health services, professional clinical guidelines, public health agencies, and established hospitals. We link claims to relevant resources, distinguish general guidance from an individual treatment plan, and include publication dates. Search topics help us understand readers’ questions; they do not determine clinical advice.</p><h2>What we believe good guidance includes</h2><ul><li>Practical explanations, rather than promises of fast or guaranteed results.</li><li>Recognition that muscles need coordination and relaxation as well as strength.</li><li>Clear advice to seek individual care when symptoms or uncertainty make self-directed exercise inappropriate.</li><li>Useful questions to take to an appointment, and permission to adapt a routine to real life.</li></ul><h2>Our relationship with the app</h2><p>We make Pelvic Gym and benefit if you choose to download or subscribe to it. App links are clearly presented as links to our own product. The app offers guided workouts; it cannot diagnose a condition, examine your technique, or replace a healthcare professional. A source citation is not an endorsement of the app.</p><h2>Images and illustrations</h2><p>The journal’s lifestyle image is editorial artwork, not a real patient, clinician, testimonial, or demonstration of an exercise. The simple illustrations are decorative.</p><h2>Corrections and updates</h2><p>Found something that needs correcting? Email <a href="mailto:contact@bestme.mobi">contact@bestme.mobi</a> with the article link and the issue. Articles should be updated when their advice or sources materially change; a date is not a promise that a clinician has reviewed the text.</p><p><a href="{BASE}/#guides">Explore the guides →</a></p></article></main>'''
    save(BASE+'/about/index.html',page_shell('About Our Journal & Editorial Approach | Pelvic Gym','Learn who publishes the Pelvic Gym journal, how we use reliable health sources, and the editorial standards behind our pelvic floor education articles.',BASE+'/about/',about,page='about'))
    privacy=f'''<main id="main" class="wrap"><article class="prose-page"><p class="eyebrow">Website privacy · {DISPLAY_DATE}</p><h1>Your privacy choices.</h1><p>This notice applies to the Pelvic Gym journal at bestme.mobi/pelvic_gym, published by Aleksandr Korenev. The app has a separate <a href="/pelvic-gym-privacy-policy.html">privacy policy</a>.</p><h2>Optional Google Analytics</h2><p>If you choose “Allow analytics,” we use Google Analytics to understand which pages people visit, how they find the journal, and whether they click an App Store link. Google receives page addresses and titles, interaction events, browser and device information, and connection information such as your IP address. Google’s handling of IP addresses and location information depends on the visitor’s region. Read <a href="https://support.google.com/analytics/answer/12017362">Google’s data collection explanation</a>.</p><p>The Google tag loads only after you allow analytics. If you decline, the journal continues to work and does not load this tag or send analytics events. Your choice applies to this browser and is remembered for up to 180 days. You can change it at any time using “Privacy choices” in the footer.</p><p data-consent-status role="status">Optional analytics is off until you allow it.</p><button type="button" class="btn outline" data-privacy-choices hidden>Change privacy choices</button><h2>What we measure</h2><ul><li>Page views, visits and general traffic sources.</li><li>Clicks on our App Store badges, including the page and badge location.</li><li>Whether a reader scrolls through approximately 75% of an article. This does not prove the article was read.</li></ul><p>We do not collect the text you enter into article search, medical histories, account details or form submissions. We remove query strings and fragments from the page address sent by our tag; standard source, medium and campaign labels may be sent separately. We send only the origin of external referring websites. Public article addresses and titles still identify the topic you visited.</p><h2>Cookies and advertising</h2><p>After consent, Analytics may use cookies beginning with “pgj” to distinguish browsers and visits. These cookies are scoped to the journal and configured to expire within 180 days. They are separate from the preference stored in your browser that remembers your choice. Withdrawing consent disables future tracking and removes the journal’s Analytics cookies; it does not erase information already processed by Google.</p><p>Our website tag disables Google Signals and advertising personalization, and keeps advertising consent denied. We do not use session recordings or send user-provided contact information to Analytics. Google may process data in countries outside your own. See <a href="https://policies.google.com/privacy">Google’s privacy policy</a> and <a href="https://policies.google.com/technologies/partner-sites">how Google uses information from partner sites</a>.</p><h2>Hosting and other links</h2><p>GitHub Pages hosts this site and receives ordinary connection information when a page loads. See <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub’s privacy statement</a>. Article search and filtering run in your browser. External health resources and the App Store have their own privacy rules.</p><p>App Store links include campaign labels identifying the journal page and button location, not your identity. An App Store click does not tell us whether you installed the app.</p><h2>Contact and requests</h2><p>For privacy questions or requests about information we hold, contact <a href="mailto:contact@bestme.mobi">contact@bestme.mobi</a>. Please avoid sending medical details; this inbox does not provide healthcare.</p></article></main>'''
    save(BASE+'/privacy/index.html',page_shell('Website Privacy | Pelvic Gym','Understand optional Google Analytics, cookies, page and App Store click measurement, and how to change your privacy choices on the Pelvic Gym journal.',BASE+'/privacy/',privacy,page='privacy'))


def build_categories():
    for name,c in CATEGORIES.items():
        selected=[a for a in ARTICLES if a['category']==name]
        path=category_url(name)
        body=f"""<main id="main" class="wrap"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="{BASE}/">Pelvic Gym</a><span aria-hidden="true">/</span><a href="{BASE}/#guides">Articles</a><span aria-hidden="true">/</span><span>{e(name)}</span></nav><header class="article-header"><p class="eyebrow coral-text">{e(name)}</p><h1>{e(c['title'])}</h1><p class="article-dek">{e(c['intro'])}</p></header><section class="library" aria-label="Articles about {e(name)}"><div class="cards">{''.join(card(a) for a in selected)}</div></section><nav class="topic-navigation" aria-label="Explore more topics"><p class="eyebrow">Explore more topics</p><div>{''.join(f'<a class="filter topic-link" href="{category_url(k)}">{e(k)} ↗</a>' for k in CATEGORIES if k!=name)}</div></nav></main>"""
        schemas=[{'@context':'https://schema.org','@type':'CollectionPage','name':c['seo'],'url':ORIGIN+path,'mainEntity':{'@type':'ItemList','itemListElement':[{'@type':'ListItem','position':i+1,'name':a['title'],'url':ORIGIN+url(a)} for i,a in enumerate(selected)]}}]
        save(path+'index.html',page_shell(c['seo'],c['description'],path,body,page=c['slug'],schemas=schemas))

def build_sitemap():
    ns='http://www.sitemaps.org/schemas/sitemap/0.9'
    ET.register_namespace('',ns)
    paths=[BASE+'/']+[url(a) for a in ARTICLES]+[category_url(c) for c in CATEGORIES]+[BASE+'/about/',BASE+'/privacy/']
    root=ET.Element('{'+ns+'}urlset')
    for path in paths:
        node=ET.SubElement(root,'{'+ns+'}url');ET.SubElement(node,'{'+ns+'}loc').text=ORIGIN+path;ET.SubElement(node,'{'+ns+'}lastmod').text=next((a.get('dateModified',a.get('datePublished',DATE)) for a in ARTICLES if url(a)==path), DATE if path in [BASE+'/about/',BASE+'/privacy/'] else LATEST)
    save(BASE+'/sitemap.xml',ET.tostring(root,encoding='unicode',xml_declaration=True))
    # Preserve other top-level sitemap entries if this shared domain adds them later.
    top=ROOT/'sitemap.xml'
    if top.exists():
        index=ET.parse(top).getroot()
        if index.tag!='{'+ns+'}sitemapindex':
            raise ValueError('Existing root sitemap is not an index; merge deliberately before building.')
    else: index=ET.Element('{'+ns+'}sitemapindex')
    loc=ORIGIN+BASE+'/sitemap.xml'
    found=False
    for child in index:
        node=child.find('{'+ns+'}loc')
        if node is not None and node.text==loc:
            last=child.find('{'+ns+'}lastmod')
            if last is None: last=ET.SubElement(child,'{'+ns+'}lastmod')
            last.text=LATEST;found=True
    if not found:
        node=ET.SubElement(index,'{'+ns+'}sitemap');ET.SubElement(node,'{'+ns+'}loc').text=loc;ET.SubElement(node,'{'+ns+'}lastmod').text=LATEST
    top.write_text(ET.tostring(index,encoding='unicode',xml_declaration=True))
    robots=ROOT/'robots.txt'
    text=robots.read_text() if robots.exists() else 'User-agent: *\nAllow: /\n'
    if 'Sitemap: '+ORIGIN+'/sitemap.xml' not in text: text=text.rstrip()+'\n\nSitemap: '+ORIGIN+'/sitemap.xml\n'
    robots.write_text(text)

if __name__=='__main__':
    assert len(ARTICLES)==len(BY_SLUG), 'Duplicate article slugs'
    assert set(BY_SLUG).issubset(set(ORDER)), 'Unexpected article slugs'
    build_home()
    for a in ARTICLES: build_article(a)
    build_information();build_categories();build_sitemap()
    print(f'Built journal homepage, {len(ARTICLES)} articles, editorial and privacy pages, and sitemaps.')
